const rows = $('Load Queued Videos').all().map(i => i.json || {});
const products = $('Load Products For Packshot').all().map(i => i.json || {});
const queuedRows = rows.filter(r => r.approval_status === 'approved' && r.render_status === 'queued');
const target = queuedRows[queuedRows.length - 1] || rows[rows.length - 1];
if (!target || !target.video_key) return [];

const TOKEN = $env.HF_TOKEN || '';
const matchedProd = products.find(p => p.product_key === target.product_key) || {};
const dePackshotUrl = String(matchedProd.packshot_image_url || '');
const refVideoUrl = String(target.final_video_url || '');
const productName = String(matchedProd.product_name || target.product_key || '').slice(0, 140);

let scenes = [];
try { scenes = JSON.parse(target.scenes_json || '[]'); } catch (e) { scenes = []; }
if (!scenes.length || !/^https:\/\/api\.apify\.com\/v2\/key-value-stores\/[^/]+\/records\/[^?]+\.mp4\?/i.test(refVideoUrl)) {
  return [{ json: { ...target, render_status: 'blocked_no_reference' } }];
}

let analysis = null;
try {
  analysis = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://ffmpeg.mafrapi.eu/api/ffmpeg/analyze-reference',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ videoUrl: refVideoUrl }),
    timeout: 120000
  });
} catch (e) { analysis = null; }

const refScenes = (analysis && Array.isArray(analysis.scenes) ? analysis.scenes : [])
  .filter(s => s && s.reference_clip_url && Number(s.duration_sec) >= 2);
if (!refScenes.length) return [{ json: { ...target, render_status: 'blocked_no_reference' } }];

// VISION FILTER: judge each scene's first frame — real product demo footage only,
// no baked-in screenshots, receipts, comment stickers, UI recordings or mismatched products.
const self = this;
const VISION_MODELS = ['Qwen/Qwen3-VL-30B-A3B-Instruct', 'Qwen/Qwen2.5-VL-72B-Instruct'];
async function judgeScene(s) {
  const frameUrl = (s.frames && s.frames[0] && s.frames[0].url) || '';
  if (!TOKEN || !frameUrl) return { ok: true, reason: 'no_frame_or_token' };
  let lastErr = '';
  for (const model of VISION_MODELS) {
    try {
      const resp = await self.helpers.httpRequest({
        method: 'POST',
        url: 'https://router.huggingface.co/v1/chat/completions',
        headers: { Authorization: 'Bearer ' + TOKEN, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: model,
          temperature: 0,
          max_tokens: 150,
          messages: [{
            role: 'user',
            content: [
              { type: 'text', text: 'Judge this frame from a product demo video for reuse in a German TikTok Shop ad for: ' + productName + '. Answer ONLY JSON {"ok":true|false,"reason":"max 10 words"}. ok=false if the frame shows: screenshot/receipt/order page, baked-in text overlays or comment stickers, phone/computer screen recording, a clearly different product type, no physical product visible, or mostly logo/graphic cards. ok=true only if a real physical matching-type product is visibly used or held.' },
              { type: 'image_url', image_url: { url: frameUrl } }
            ]
          }]
        }),
        timeout: 45000
      });
      const txt = String(resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content || '');
      const m = txt.match(/\{[\s\S]*\}/);
      const j = m ? JSON.parse(m[0]) : { ok: false };
      return { ok: !!j.ok, reason: String(j.reason || 'unparseable'), model };
    } catch (e) {
      lastErr = model + ':' + String((e && (e.message || (e.response && JSON.stringify(e.response.body)))) || e).replace(/\s+/g, ' ').slice(0, 70);
    }
  }
  return { ok: false, reason: 'vision_error:' + lastErr };
}

const verdicts = await Promise.all(refScenes.map(s => judgeScene(s)));
const good = refScenes.filter((s, i) => verdicts[i].ok);
const rejected = refScenes.filter((s, i) => !verdicts[i].ok)
  .map(s => ({ scene_no: s.scene_no, reason: verdicts[refScenes.indexOf(s)].reason }));

// Need at least 2 real demo clips total; otherwise block instead of faking content.
if (good.length < 2) {
  return [{ json: { ...target, render_status: 'blocked_no_reference', vision_rejections_json: JSON.stringify(rejected) } }];
}

const lastIdx = scenes.length - 1;
const enrichedScenes = scenes.map((s, i) => {
  const isLast = i === lastIdx && scenes.length > 1;
  if (isLast) {
    return { ...s, ref_scene_no: null, reference_clip_url: '', generated_clip_url: '', generated_image_url: dePackshotUrl || s.generated_image_url || '' };
  }
  if (i < good.length) {
    const pick = good[i];
    return {
      ...s,
      ref_scene_no: pick.scene_no,
      reference_clip_url: pick.reference_clip_url,
      ref_start_sec: pick.start_sec,
      ref_end_sec: pick.end_sec,
      vision_verdict: 'ok',
      generated_clip_url: pick.reference_clip_url,
      generated_image_url: (pick.frames && pick.frames[0] && pick.frames[0].url) || dePackshotUrl || ''
    };
  }
  // FALLBACK tier 2: not enough verified clips -> German packshot zoom segment.
  return { ...s, ref_scene_no: null, reference_clip_url: '', vision_verdict: 'packshot_fallback', generated_clip_url: '', generated_image_url: dePackshotUrl || s.generated_image_url || '' };
});

return [{
  json: {
    ...target,
    scenes_json: JSON.stringify(enrichedScenes),
    reference_audio_url: analysis.audio_url || '',
    vision_stats: 'usable=' + good.length + '/' + refScenes.length,
    vision_rejections_json: JSON.stringify(rejected),
    render_status: 'ready_for_ffmpeg'
  }
}];

const verdictItems = $input.all().map(i => i.json || {});
const sceneItems = $('Analyze Reference Scenes').all().map(i => i.json || {});
if (!sceneItems.length || !sceneItems[0].__target) return [];
const first = sceneItems[0];
const target = first.__target;
const dePackshotUrl = first.__de_packshot || '';

const good = [];
const rejected = [];
sceneItems.forEach((s, i) => {
  const j = verdictItems[i] || {};
  const ref = { ref_scene_no: s.ref_scene_no, reference_clip_url: s.reference_clip_url, ref_start_sec: s.ref_start_sec, ref_end_sec: s.ref_end_sec, frame_url: s.frame_url || '' };
  const content = (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '';
  const m = String(content).match(/\{[\s\S]*\}/);
  let ok = false, reason = 'vision_error';
  try { const v = m ? JSON.parse(m[0]) : null; ok = !!(v && v.ok); reason = v && v.reason ? String(v.reason) : (j.choices ? 'unparseable' : 'vision_error'); } catch (e) { reason = 'unparseable'; }
  if (ok) good.push(ref); else rejected.push({ scene_no: s.ref_scene_no, reason });
});

let scenes = [];
try { scenes = JSON.parse(target.scenes_json || '[]'); } catch (e) { scenes = []; }
if (!scenes.length || good.length < 2) {
  return [{ json: { ...target, render_status: 'blocked_no_reference', vision_rejections_json: JSON.stringify(rejected) } }];
}

const lastIdx = scenes.length - 1;
const enrichedScenes = scenes.map((s, i) => {
  const isLast = i === lastIdx && scenes.length > 1;
  if (isLast) return { ...s, ref_scene_no: null, reference_clip_url: '', generated_clip_url: '', generated_image_url: dePackshotUrl || s.generated_image_url || '' };
  if (i < good.length) {
    const pick = good[i];
    return { ...s, ref_scene_no: pick.ref_scene_no, reference_clip_url: pick.reference_clip_url, ref_start_sec: pick.ref_start_sec, ref_end_sec: pick.ref_end_sec, vision_verdict: 'ok', generated_clip_url: pick.reference_clip_url, generated_image_url: pick.frame_url || dePackshotUrl || '' };
  }
  return { ...s, ref_scene_no: null, reference_clip_url: '', vision_verdict: 'packshot_fallback', generated_clip_url: '', generated_image_url: dePackshotUrl || s.generated_image_url || '' };
});

return [{ json: { ...target, scenes_json: JSON.stringify(enrichedScenes), reference_audio_url: first.__audio_url || '', vision_stats: 'usable=' + good.length + '/' + sceneItems.length, vision_rejections_json: JSON.stringify(rejected), render_status: 'ready_for_ffmpeg' } }];
